import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] a = new int[10000];
        for (int i = 0; i < 10000; i++) {
            a[i] = 0;
        }
        for (int i = 0; i < n; i++) {
            int t = sc.nextInt();
            a[t]++;
        }
        int t = sc.nextInt();
        int ans = 0;
        for (int i = 1; i <= 1000; i++) {
            int cur = 0;
            for (int j = i; j <= i + t; j++) {
                if (j < a.length) {
                    cur += a[j];
                }
            }
            if (cur > ans) {
                ans = cur;
            }
        }
        System.out.println(ans);
        sc.close();
    }
}
